  input  wire [23:0] p_in;
  output reg  [23:0] p_out;
  input  wire [7:0] w_in;
  output reg  [7:0] w_out;
  wire [15:0] prod = $signed(a_in) * $signed(w_in);
  always @(posedge clk) begin
    if (rst) begin
      a_out <= 8'd0; p_out <= 24'd0; w_out <= 8'd0;
    end else begin
      a_out <= a_in;
      w_out <= w_in;
      p_out <= p_in + {{8{prod[15]}}, prod};
    end
  end
endmodule

module feed_cell (clk, rst, in, out);
  input  wire       clk;
  input  wire       rst;
  input  wire [7:0] in;
  output reg  [7:0] out;
